INSERT IGNORE INTO products(id,category_id,name,slug,price,old_price,stock,image,description,sold,rating,status,created_at) VALUES('sony-xm5','elektronik','Sony WH-1000XM5 Wireless Headphones','sony-xm5',3299000,4499000,24,'/images/headphones.webp','Nikmati musik lebih dekat dengan headphone wireless berdesain ringan. Dilengkapi noise cancelling, koneksi Bluetooth, dan bantalan lembut untuk aktivitas sehari-hari.',328,'4.9','active','2026-11-04T08:00:00Z');
